import{_ as t,a0 as l,w as o,s as d,ao as c,I as p,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"彙總你在 Linux 上的命令使用情況 | LCTT x X-CMD","titleTemplate":false,"description":"彙總你在 Linux 上的命令使用情況 | LCTT (202008) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"彙總你在 Linux 上的命令使用情況 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"彙總你在 Linux 上的命令使用情況 | LCTT (202008) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202008/20200716 Summarizing your command usage on Linux","title":"彙總你在 Linux 上的命令使用情況","tag":"202008","desc":""},"relativePath":"202008/20200716 Summarizing your command usage on Linux.md","filePath":"[post].md"}'),r={name:"202008/20200716 Summarizing your command usage on Linux.md"};function h(g,s,k,u,b,y){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="彙總你在-linux-上的命令使用情況" tabindex="-1">彙總你在 Linux 上的命令使用情況 <a class="header-anchor" href="#彙總你在-linux-上的命令使用情況" aria-label="Permalink to “彙總你在 Linux 上的命令使用情況”">​</a></h1><blockquote><p>使用合適的命令，你可以快速瞭解 Linux 系統上使用的命令以及執行的頻率。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202008/14/221303ln67fl62nsfb7nys.jpg" alt=""></p><p>彙總 Linux 系統上使用的命令只需一串相對簡單的命令以及幾條管道將它們綁定在一起。當你的歷史記錄緩衝區保留了最近的 1,000 或 2,000 條命令時，總結你的命令活動可能會變得很乏味。這篇文章提供了一種方便的方法來彙總命令的使用情況，並高亮顯示最常用的命令。</p><p>首先，請記住，典型的命令歷史記錄可能看起來像這樣。請注意，命令是顯示在命令序列號之後，並緊跟其參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>91  sudo apt-get install ccrypt</span></span>
<span class="line"><span>     ^</span></span>
<span class="line"><span>     +-- command</span></span></code></pre></div><p>請注意，<code>history</code> 命令遵循 <code>HISTSIZE</code> 的設置，這會決定保留多少條命令。可能是 500、1,000 或更多。如果你不喜歡它的設置，那麼可以在 <code>.bashrc</code> 或其他啓動文件中添加或更改 <code>HISTSIZE</code> 設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTSIZE</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ history | wc -l</span></span>
<span class="line"><span>1000</span></span>
<span class="line"><span>$ grep HISTSIZE ~/.bashrc</span></span>
<span class="line"><span># for setting history length see HISTSIZE and HISTFILESIZE in bash(1)</span></span>
<span class="line"><span>HISTSIZE=1000</span></span></code></pre></div><p>記下大量命令的主要好處之一是，它可以讓你輕鬆地重新運行過去使用的命令，而不必重新輸入或記住它們。它還能讓你輕鬆地查看你在一個任務中已經做了多少工作。單獨使用 <code>history</code> 命令時，你會看到類似下面這樣，最早的在最前面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history</span></span>
<span class="line"><span>    7  vi tasks</span></span>
<span class="line"><span>    8  alias</span></span>
<span class="line"><span>    9  echo $HISTTIMEFORMAT</span></span>
<span class="line"><span>   10  history</span></span>
<span class="line"><span>   11  date</span></span>
<span class="line"><span>   …</span></span></code></pre></div><p>查看最新使用命令需要查看記錄的命令的尾部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | tail -4</span></span>
<span class="line"><span> 1007  echo $HISTSIZE</span></span>
<span class="line"><span> 1008  history | wc -l</span></span>
<span class="line"><span> 1009  history</span></span>
<span class="line"><span> 1010  history | tail -4</span></span></code></pre></div><p>另外，你可以使用 <code>tail</code> 命令查看 <code>.bash_history</code> 文件的尾部，但是 <code>history</code> 命令顯示的數字可以讓你輸入如 <code>!1010</code> 這樣的數字重新運行命令，這點通常更有用。</p><p>要提供已使用命令的彙總（例如 <code>vi</code> 和 <code>echo</code>），你可以首先使用 <code>awk</code> 將命令與 <code>history</code> 中保存的其他信息分隔開來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39;</span></span>
<span class="line"><span>vi</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span>echo</span></span>
<span class="line"><span>history</span></span>
<span class="line"><span>date</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>如果你將歷史記錄中的命令列表傳遞給 <code>sort</code> 命令以按字母順序對命令進行分組，那麼會得到以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort</span></span>
<span class="line"><span>7z</span></span>
<span class="line"><span>7z</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span>apropos</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>接下來，將 <code>sort</code> 命令的輸出傳遞給 <code>uniq -c</code> ，這將計算每個命令使用了多少次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort | uniq -c</span></span>
<span class="line"><span>      2 7z</span></span>
<span class="line"><span>      1 alias</span></span>
<span class="line"><span>      2 apropos</span></span>
<span class="line"><span>     38 cd</span></span>
<span class="line"><span>     21 chmod</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>最後，添加第二個 <code>sort</code> 命令按倒序對命令組計數進行排序，這將先列出最常用的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ history | awk &#39;{print $2}&#39; | sort | uniq -c | sort -nr</span></span>
<span class="line"><span>    178 ls</span></span>
<span class="line"><span>     95 vi</span></span>
<span class="line"><span>     63 cd</span></span>
<span class="line"><span>     53 sudo</span></span>
<span class="line"><span>     41 more</span></span>
<span class="line"><span>…</span></span></code></pre></div><p>這樣可以讓你瞭解使用最多的命令，但不會包括任何你可能故意從歷史記錄文件中刪除的命令，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HISTIGNORE=&quot;pwd:clear:man:history&quot;</span></span></code></pre></div><h3 id="當修改了歷史記錄格式時" tabindex="-1">當修改了歷史記錄格式時 <a class="header-anchor" href="#當修改了歷史記錄格式時" aria-label="Permalink to “當修改了歷史記錄格式時”">​</a></h3><p>對於默認的歷史記錄格式，<code>history</code> 命令輸出中的第一個字段將是每個命令的序號，第二個字段是使用的命令。因此，上面所有 <code>awk</code> 命令都設置成顯示 <code>$2</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print $2}&#39;\\&#39;&#39; | sort | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>如果你像下面那樣將日期和時間添加了到 <code>history</code> 命令中，那麼你還必須修改所設置的別名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HISTTIMEFORMAT</span></span>
<span class="line"><span>%d/%m/%y %T</span></span></code></pre></div><p>這個日期/時間信息有時會很有幫助，但是這意味着你必須在選擇 <code>history</code> 命令的第 4 個字段而不是第 2 個字段來彙總命令，因為你的歷史記錄條目將如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>91  05/07/20 16:37:39 sudo apt-get install ccrypt</span></span>
<span class="line"><span>                       ^</span></span>
<span class="line"><span>                       +-- command</span></span></code></pre></div><p>因此，在將 <code>$2</code> 變為 <code>$4</code> 之後，用於檢查 <code>history</code> 命令的別名將改為這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print $4}&#39;\\&#39;&#39; | sort | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>可將別名保存在 <code>.bashrc</code> 或其他啓動文件中，請確保在 <code>$</code> 符號前面插入反斜槓，以便 bash 不會嘗試解釋 <code>$4</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print \\$2}&#39;\\&#39;&#39; | uniq -c | sort -nr&#39;</span></span>
<span class="line"><span>alias cmds=&#39;history | awk &#39;\\&#39;&#39;{print \\$4}&#39;\\&#39;&#39; | uniq -c | sort -nr&#39;</span></span></code></pre></div><p>請注意，日期和時間信息與命令本身保存在歷史記錄文件的不同行中。因此，添加此信息後，bash 歷史記錄文件的行數將增加一倍，儘管在 <code>history</code> 命令輸出時不會：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l .bash_history</span></span>
<span class="line"><span>2000 .bash_history</span></span>
<span class="line"><span>$ history | wc -l</span></span>
<span class="line"><span>1000</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你可以隨時決定要保留多少命令歷史記錄，哪些命令不值得記錄，以使你的命令摘要最有用。</p><hr>`,39)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.networkworld.com/article/3567050/summarizing-your-command-usage-on-linux.html"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3567050/summarizing-your-command-usage-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const C=t(r,[["render",h]]);export{x as __pageData,C as default};
